
// This script uploads the JSON output from a SageMaker Batch Transform job
// to a Firestore collection.

const { initializeApp, cert } = require('firebase-admin/app');
const { getFirestore } = require('firebase-admin/firestore');
const fs = require('fs');
const path = require('path');

// --- CONFIGURATION ---

// Path to your Firebase service account key JSON file
// IMPORTANT: Download this from your Firebase project settings
const SERVICE_ACCOUNT_PATH = './serviceAccountKey.json'; 

// Path to the prediction file generated by your batch_predict.py script
const PREDICTIONS_FILE_PATH = '../sagemaker-demand/predictions.json';

// Name of the Firestore collection to upload to
const FIRESTORE_COLLECTION = 'ai_reports';

// --- SCRIPT LOGIC ---

if (!fs.existsSync(path.resolve(__dirname, SERVICE_ACCOUNT_PATH))) {
    console.error(`ERROR: Firebase service account key not found at '${SERVICE_ACCOUNT_PATH}'.`);
    console.error('Please download it from your Firebase Project Settings > Service accounts and place it in the /scripts directory.');
    process.exit(1);
}

const serviceAccount = require(SERVICE_ACCOUNT_PATH);

initializeApp({
  credential: cert(serviceAccount)
});

const db = getFirestore();
const predictionsFilePath = path.resolve(__dirname, PREDICTIONS_FILE_PATH);

if (!fs.existsSync(predictionsFilePath)) {
    console.error(`ERROR: Predictions file not found at '${PREDICTIONS_FILE_PATH}'.`);
    console.error('Please run the `sagemaker-demand/batch_predict.py` script first to generate forecasts.');
    process.exit(1);
}

const predictions = JSON.parse(fs.readFileSync(predictionsFilePath, 'utf8'));

async function uploadPredictions() {
    if (!predictions || predictions.length === 0) {
        console.log('No predictions to upload.');
        return;
    }

    console.log(`Found ${predictions.length} predictions. Starting upload to '${FIRESTORE_COLLECTION}'...`);
    
    const batch = db.batch();

    predictions.forEach((prediction, index) => {
        const docRef = db.collection(FIRESTORE_COLLECTION).doc();
        
        const report = {
            ...prediction,
            createdAt: new Date(prediction.prediction_date), // Use prediction date for consistency
            batchUploadTime: new Date(),
        };
        
        batch.set(docRef, report);
    });

    try {
        await batch.commit();
        console.log(`✅ Successfully uploaded ${predictions.length} prediction reports to Firestore.`);
    } catch (error) {
        console.error('🔥 Error uploading predictions to Firestore:', error);
    }
}

uploadPredictions();
